-- NEWER VGM Other Games — Rare (publisher section)
--
-- Source: reference/NEWER VGM Sound Sources - Other Games.csv lines 10546-10844.
-- 18 game/album records, ~260 usage rows.
--
-- First batch from the "Other Games" file (27,801 lines, 729 games,
-- 47 publisher sections). Picking Rare as the lead-off because the
-- catalogue is iconic and bounded (B-K family + Conker + Star Fox
-- Adventures + GoldenEye + Killer Instinct).
--
-- Composer credits this batch (from in-CSV "(Music by:" notes only):
--   - Killer Instinct (SNES) + Killer Cuts album — Robin Beanland, Graeme Norgate
--   - Banjo-Kazooie — Grant Kirkhope
--   - Star Fox Adventures — David Wise, Ben Cullum
--   Other Rare games (GoldenEye, Conker, Perfect Dark, etc.) lack
--   explicit in-CSV credits and so leave composers NULL despite the
--   well-known authorship — Rule 2 (don't add data the CSV doesn't supply).
--
-- New manufacturers introduced this batch:
--   - BOSS                          (used standalone in GoldenEye stuff_to_find)
--   - Roland/BOSS                   (composite spelling Roland uses for the
--                                   DR-660 drum machine in Killer Cuts —
--                                   distinct from BOSS standalone per Rule 2)
--   - Microsoft                     (GS Wavetable Synth in Star Fox Adventures)
--   - Q-Up Arts                     (Voices of Native America)
--   - EastWest & Masterbits         (composite — Peter Siedlaczek's Orchestra)
--   - Green Sound & Exy Music Library (Volume 2 Pipa & LuiQin)
--
-- New products this batch (selection — INSERT OR IGNORE on all):
--   - Roland L-CD1, L-CDP-01 Drums & Cymbals Vol. 1, L-CDP-03 Orchestral
--     Percussion Vol. 1, L-CDP-04 Orchestral Winds Vol. 1, L-CDP-06
--     Brass Sections Vol. 1, L-CDP-08 Symphony Orchestra Vol. 1,
--     L-CDP-11 Africa Vol. 1, L-CD702 Orchestral Family Vol. 1, Vol. 2,
--     U-220
--   - Roland JV-1080 (existed), Rhythm Set "-" placeholder preserved
--     verbatim
--   - Roland SR-JV80-01 Pop, SR-JV80-04 Vintage Synth, SR-JV80-06 Dance
--   - E-MU Systems Proteus/1, Proteus/2, Morpheus, Liveware ESC SoundFont Library
--   - KORG WAVESTATION EX, 01/W Pro (distinct from WAVESTATION SR / 01/W
--     per Rule 2 — different KORG model)
--   - BOSS DR-660, Roland/BOSS DR-660 (same model, two contributor spellings)
--   - Yamaha DX7, SY77
--   - Ensoniq TS-12
--   - Best Service Albie Donnelly's Killer Horns, Gigapack 2
--   - Masterbits Climax-Collection Vol. 2 - Classic, Climax-Collection
--     Vol. 3 Guitars (NO hyphen between "Vol. 3" and "Guitars" — distinct
--     from existing "Climax-Collection Vol. 3 - Guitars" per Rule 2),
--     Peter Siedlaczek's Orchestra Plus
--   - EastWest & Masterbits / Peter Siedlaczek's Orchestra
--   - EastWest Steve Stevens Guitar (added Other-a), Symphonic Choirs (added S14)
--   - AMG Megabass REMIX!, Megabass REMIX! II
--   - Polestar Magnetics XL1 (distinct from existing The X-Static Goldmine)
--   - Spectrasonics Heart of Africa Vol. 1, Heart of Africa Vol. 2 (distinct
--     from existing "Heart of Africa" no-Vol per Rule 2), Distorted Reality
--   - Sound Ideas Lucasfilm Sound Effects Library, Sci-Fi Series 8000,
--     Series 1000
--   - Hollywood Edge Cartoon Trax
--   - Microsoft GS Wavetable Synth
--   - Q-Up Arts Voices of Native America
--   - EastWest & Masterbits Peter Siedlaczek's Orchestra
--   - Green Sound & Exy Music Library Volume 2 Pipa & LuiQin
--
-- Verbatim preservations (Rule 2 / Rule 11):
--   - "Banjo-Kazooie ★★" — the ★★ markers are contributor confidence
--     indicators, not part of the game title. Stripped from title;
--     mentioned in notes.
--   - Cross-media sample row for Banjo-Kazooie "Sample: Nintendo - Game Boy"
--     → raw_source, product_id NULL.
--   - Banjo-Tooie row 10704 "All other documented instruments come from
--     Banjo-Kazooie." → preserved as game notes (not a usage row).
--   - Killer Cuts split from Killer Instinct as a separate game record
--     (album-companion convention from Section 1 Atlus arrange-albums).
--   - Conker: Live & Reloaded line 10822-10824 lists Spectrasonics
--     Distorted Reality + Symphony of Voices + Vienna Symphonic Library
--     all marked "Credited" — preserved in notes column.
--   - Sea of Thieves Live Recording credits for Robin Beanland on
--     Concertina, Electro-Acoustic Hurdy-Gurdy, Rhythm Bones, Waterphone —
--     all preserved as raw_source with the instrument in parens.
--
-- Position numbering: per-game positions start at 1, monotonic across
-- main and stuff_to_find.

INSERT OR IGNORE INTO manufacturers (name) VALUES
  ('BOSS'),
  ('Roland/BOSS'),
  ('Microsoft'),
  ('Q-Up Arts'),
  ('EastWest & Masterbits'),
  ('Green Sound & Exy Music Library');

